import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"查询改写","description":"","frontmatter":{"title":"查询改写","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/query-rewrite.md","filePath":"cs/query-rewrite.md","lastUpdated":1789023840000}'),c={name:"cs/query-rewrite.md"};function m(E,a,_,u,B,f){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="查询改写" tabindex="-1">查询改写 <a class="header-anchor" href="#查询改写" aria-label="Permalink to &quot;查询改写&quot;">​</a></h1><div class="epigraph"><p>先用代数律把树变得更瘦，再估代价；下推与结合律改的是形状，不是用户写的那句话。</p><footer>—— 据 Ullman 对逻辑优化；Chaudhuri 对优化器架构的整理</footer></div><p><a href="/cs/histogram-card">上一课</a>给计划树上的数字。本课不重写选择率公式。缺口是：许多等价逻辑树，有的让选择更早、连接更小。改写在逻辑层用代数律变换，再交给物理搜索与代价。没有改写，优化器只能在用户写出的那一棵歪树上估数字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户可能先写笛卡尔积再过滤，或把能下推的谓词留在顶层。指称相同，中间结果可以差几个数量级。缺口不是新 SQL，而是<strong>保持指称的变换</strong>：选择下推、投影下推、连接结合律与交换律、把子查询改成连接。本课只做逻辑等价，不保证改完一定更快——更快由代价判定。</p><p><span class="marginnote">集合语义下选择与连接交换较干净；NULL 与包会打碎部分律。SQL 课已承认三值；改写器必须标哪些变换在当前语义下合法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 SQL 收成逻辑树后，反复应用：\\(\\sigma_\\theta(R\\bowtie S)\\) 在 \\(\\theta\\) 只涉及 \\(R\\) 时变成 \\(\\sigma_\\theta(R)\\bowtie S\\)；投影只保留后继需要的列；连接树按结合律重括号。视图展开是改写的一种：把视图名换成定义树。本课不引入基于规则的引擎实现，只锁定变换前后指称相同。</p>',8)),(e(),n(h,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQL%5B%22%E5%A3%B0%E6%98%8E%20SQL%22%5D%20--%3E%20LOG%5B%22%E9%80%BB%E8%BE%91%E6%A0%91%22%5D%0A%20%20LOG%20--%3E%20RW%5B%22%E4%BB%A3%E6%95%B0%E6%94%B9%E5%86%99%22%5D%0A%20%20RW%20--%3E%20EST%5B%22%E4%BB%A3%E4%BB%B7%20%2B%20%E7%89%A9%E7%90%86%E6%90%9C%E7%B4%A2%22%5D%0A%20%20RW%20--%3E%20NF%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%8C%83%E5%BC%8F%E4%B8%8E%E5%88%86%E8%A7%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>改写缩小中间基数，使后课的哈希表与排序输入变小；也可能为了用某一索引而<strong>故意</strong>保留某个谓词形状。启发式（始终下推）与基于代价的变换可以并存：先做几乎总赚的下推，再对连接顺序做代价搜索。相关子查询去相关，是把演算写法改回连接，以便用<a href="/cs/join-algorithms">连接算法</a>。</p><p>本课不把「提示」当模型。提示是绕过搜索的工程旋钮；主干仍是等价变换加代价。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>改写不修复错误的统计，也不替代完整性。不能把有副作用的函数随便下推。分组、极限、窗口对交换律不友好，本课只点名：这些算子是改写的防火墙。也不把规范化（模式分解）与查询改写混成一步——下一课动的是模式，不是这一棵查询树。</p><p>外连接会挡住某些下推：NULL 填充使「先过滤再连接」与「先连接再过滤」不再同指称。后课默认：优化器先改逻辑树再估代价；谈到等价，指的是代数指称，不是计划字符串相同。</p><p>改写器与代价估计交替：先做几乎总合法的下推，再对连接顺序搜。指称不变是硬约束，快是软目标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>相关子查询去相关是为了进入连接算法，不是为了换一种 SQL 方言。</p></li><li><p>有副作用的 UDF 是改写防火墙，本课不当成可下推的 \\(\\sigma\\)。</p></li><li><p>代价已在；本课用代数律改逻辑树的形状。</p></li><li><p>下推与结合律保指称；快不快仍看估计。</p></li><li><p>模式为何难改写、要不要分解，是后课缺口。</p></li><li><p>出处：Garcia-Molina, Ullman and Widom；Chaudhuri, <em>An Overview of Query Optimization</em>, 1998。</p></li></ul>',9))])}const q=o(c,[["render",m]]);export{S as __pageData,q as default};
